688→            if (state.currentText.trim()) {
689→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
690→              state.segments.push({ type: segType, text: state.currentText });
691→              state.currentText = '';
692→            }
693→            state.segments.push({ type: 'user_question', questionData: data });
694→            updateMessages(msgs =>
695→              msgs.map(m =>
696→                m.id === assistantId
697→                  ? { ...m, segments: [...state.segments] }
698→                  : m
699→              )
700→            );
701→          },
702→        },
703→        controller.signal,
704→        userSessionId,
705→        convId,
706→      );
707→    },
708→    [flushTextForStream, refreshTables, userSessionId]
709→  );
710→
711→  const deleteMessage = useCallback(
712→    (messageIndex: number) => {
713→      const convId = activeConversationIdRef.current;
714→      // Only block if this specific conversation is streaming
715→      if (convId && streamStatesRef.current.has(convId)) return;
716→
717→      // Store remaining messages as history for Langfuse context on next send
718→      setMessages((prev) => {
719→        const remaining = prev.slice(0, messageIndex);
720→        pendingHistoryRef.current = remaining
721→          .filter((m) => m.role === 'user' || m.role === 'assistant')
722→          .map((m) => ({ role: m.role, content: m.content }));
723→        return remaining;
724→      });
725→
726→      // Persist the truncation to the backend
727→      if (convId) {
728→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
729→          method: 'DELETE',
730→        }).catch(() => {
731→          // Best-effort: if this fails the UI is already updated
732→        });
733→        // Invalidate cache so switching back loads from backend
734→        messagesCacheRef.current.delete(convId);
735→      }
736→
737→      // Clear session so next message starts fresh
738→      sessionIdRef.current = null;
739→    },
740→    []
741→  );
742→
743→  const respondToQuestion = useCallback(
744→    async (questionId: string, answers: string[], freeText?: string) => {
745→      // Find the stream state that contains this question
746→      let targetState: StreamState | undefined;
747→      let targetConvId: string | null = null;
748→
749→      // Search all active streams for the question
750→      for (const [cid, state] of streamStatesRef.current) {
751→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
752→          targetState = state;
753→          targetConvId = cid;
754→          break;
755→        }
756→      }
757→
758→      if (targetState) {
759→        const segIdx = targetState.segments.findIndex(
760→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
761→        );
762→        if (segIdx !== -1) {
763→          targetState.segments[segIdx] = {
764→            ...targetState.segments[segIdx],
765→            userAnswer: answers,
766→            userFreeText: freeText,
767→          };
768→          targetState.messages = targetState.messages.map(m =>
769→            m.id === targetState!.assistantId
770→              ? { ...m, segments: [...targetState!.segments] }
771→              : m
772→          );
773→          if (activeConversationIdRef.current === targetConvId) {
774→            setMessages(targetState.messages);
775→          }
776→        }
777→      }
778→
779→      // POST to backend
780→      try {
781→        await fetch('/api/chat/respond', {
782→          method: 'POST',
783→          headers: {
784→            'Content-Type': 'application/json',
785→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
786→          },
787→          body: JSON.stringify({
788→            question_id: questionId,
789→            answers,
790→            free_text: freeText || null,
791→          }),
792→        });
793→      } catch (e) {
794→        console.error('Failed to respond to question:', e);
795→      }
796→    },
797→    [userSessionId]
798→  );
799→
800→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
801→    const outgoing = outgoingConversationId || null;
802→    const incoming = incomingConversationId || null;
803→    activeConversationIdRef.current = incoming;
804→
805→    // Save outgoing conversation's messages to cache (only if not streaming --
806→    // streaming conversations keep their state in streamStatesRef)
807→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
808→      const currentMsgs = messagesRef.current;
809→      if (currentMsgs.length > 0) {
810→        messagesCacheRef.current.set(outgoing, currentMsgs);
811→      }
812→    }
813→
814→    // Check if incoming conversation has an active stream (re-attachment)
815→    if (incoming) {
816→      const streamState = streamStatesRef.current.get(incoming);
817→      if (streamState) {
818→        // Re-attach: use live stream messages
819→        setMessages(streamState.messages);
820→        setIsStreaming(true);
821→        return;
822→      }
823→    }
824→
825→    // No active stream -- use backend data or cache
826→    let finalMsgs = msgs;
827→    if (incoming) {
828→      const cached = messagesCacheRef.current.get(incoming);
829→      if (cached && cached.length > 0 && cached.length > msgs.length) {
830→        finalMsgs = cached;
831→      }
832→      messagesCacheRef.current.delete(incoming);
833→    }
834→
835→    setMessages(finalMsgs);
836→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
837→    setIsStreaming(hasStreamingMsg);
838→    sessionIdRef.current = null;
839→    pendingHistoryRef.current = null;
840→  }, []);
841→
842→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
843→    const outgoing = outgoingConversationId || null;
844→    activeConversationIdRef.current = null;
845→
846→    // Save outgoing messages to cache if not streaming
847→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
848→      const currentMsgs = messagesRef.current;
849→      if (currentMsgs.length > 0) {
850→        messagesCacheRef.current.set(outgoing, currentMsgs);
851→      }
852→    }
853→
854→    setMessages([]);
855→    setIsStreaming(false);
856→    sessionIdRef.current = null;
857→    pendingHistoryRef.current = null;
858→  }, []);
859→
860→  return (
861→    <AgentContext.Provider
862→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
863→    >
864→      {children}
865→    </AgentContext.Provider>
866→  );
867→}
