  9→function formatDuration(ms: number): string {
 10→  if (ms < 1000) return `${ms}ms`;
 11→  const seconds = Math.round(ms / 1000);
 12→  if (seconds < 60) return `${seconds}s`;
 13→  const minutes = Math.floor(seconds / 60);
 14→  const remainingSeconds = seconds % 60;
 15→  return remainingSeconds > 0 ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
 16→}
 17→
 18→export function UserQuestion({
 19→  questionData,
 20→  userAnswer,
 21→  userFreeText,
 22→  answerDurationMs,
 23→}: {
 24→  questionData: UserQuestionData;
 25→  userAnswer?: string[];
 26→  userFreeText?: string;
 27→  answerDurationMs?: number;
 28→}) {
 29→  const { t } = useTranslation();
 30→  const { respondToQuestion } = useAgent();
 31→  const [selected, setSelected] = useState<Set<string>>(new Set());
 32→  const [freeText, setFreeText] = useState('');
 33→  const [showFreeText, setShowFreeText] = useState(false);
 34→  const isAnswered = !!userAnswer;
 35→
 36→  const handleOptionClick = (label: string) => {
 37→    if (isAnswered) return;
 38→    if (questionData.multiSelect) {
 39→      setSelected((prev) => {
 40→        const next = new Set(prev);
 41→        if (next.has(label)) next.delete(label);
 42→        else next.add(label);
 43→        return next;
 44→      });
 45→    } else {
 46→      // Single-select: submit immediately
 47→      respondToQuestion(questionData.questionId, [label]);
 48→    }
 49→  };
 50→
 51→  const handleSubmitMulti = () => {
 52→    if (isAnswered) return;
 53→    const answers = [...selected];
 54→    if (showFreeText && freeText.trim()) {
 55→      respondToQuestion(questionData.questionId, answers, freeText.trim());
 56→    } else {
 57→      respondToQuestion(questionData.questionId, answers);
 58→    }
 59→  };
 60→
 61→  const handleSubmitFreeText = () => {
 62→    if (isAnswered || !freeText.trim()) return;
 63→    respondToQuestion(questionData.questionId, [], freeText.trim());
 64→  };
 65→
 66→  if (isAnswered) {
 67→    return (
 68→      <div className="user-question user-question--answered">
 69→        <div className="user-question__label">
 70→          {t('questionAnswered')}
 71→          {answerDurationMs != null && (
 72→            <span className="user-question__duration">{formatDuration(answerDurationMs)}</span>
 73→          )}
 74→        </div>
 75→        <div className="user-question__question"><ReactMarkdown remarkPlugins={[remarkGfm]}>{questionData.question}</ReactMarkdown></div>
 76→        <div className="user-question__selected-answers">
 77→          {userAnswer.map((a, i) => (
 78→            <span key={i} className="user-question__selected-chip">{a}</span>
 79→          ))}
 80→          {userFreeText && (
 81→            <span className="user-question__selected-chip">{userFreeText}</span>
 82→          )}
 83→        </div>
 84→      </div>
 85→    );
 86→  }
 87→
 88→  return (
 89→    <div className="user-question">
 90→      <div className="user-question__label">{t('questionFromAgent')}</div>
 91→      <div className="user-question__question"><ReactMarkdown remarkPlugins={[remarkGfm]}>{questionData.question}</ReactMarkdown></div>
 92→      <div className="user-question__options">
 93→        {questionData.options.map((opt, i) => (
 94→          <button
 95→            key={i}
 96→            className={`user-question__option ${selected.has(opt.label) ? 'user-question__option--selected' : ''}`}
 97→            onClick={() => handleOptionClick(opt.label)}
 98→          >
 99→            {questionData.multiSelect && (
100→              <span className="user-question__checkbox">
101→                {selected.has(opt.label) ? '\u2611' : '\u2610'}
102→              </span>
103→            )}
104→            <span className="user-question__option-label">{opt.label}</span>
105→            {opt.description && (
106→              <span className="user-question__option-desc">{opt.description}</span>
107→            )}
108→          </button>
109→        ))}
110→      </div>
111→      <div className="user-question__free-text-toggle">
112→        <button
113→          className="user-question__other-btn"
114→          onClick={() => setShowFreeText(!showFreeText)}
115→        >
116→          {showFreeText ? t('hideOther') : t('other')}
117→        </button>
118→      </div>
119→      {showFreeText && (
120→        <div className="user-question__free-text">
121→          <input
122→            type="text"
123→            className="user-question__free-text-input"
124→            placeholder={t('typeYourAnswer')}
125→            value={freeText}
126→            onChange={(e) => setFreeText(e.target.value)}
127→            onKeyDown={(e) => {
128→              if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
129→                e.preventDefault();
130→                handleSubmitFreeText();
131→              }
132→            }}
133→          />
134→          <button
135→            className="user-question__submit-btn"
136→            onClick={handleSubmitFreeText}
137→            disabled={!freeText.trim()}
138→          >
139→            {t('submit')}
140→          </button>
141→        </div>
142→      )}
143→      {questionData.multiSelect && selected.size > 0 && (
144→        <button className="user-question__submit-btn user-question__submit-multi" onClick={handleSubmitMulti}>
145→          {t('submit')} ({selected.size})
146→        </button>
147→      )}
148→    </div>
149→  );
150→}
