onDone: (newSessionId) => {
  if (newSessionId) {
    state.sessionId = newSessionId;
    sessionIdRef.current = newSessionId;
  }
  flushNow();
  if (state.currentText.trim()) {
    state.segments.push({ type: 'answer', text: state.currentText });
    state.currentText = '';
  }
  const durationMs = Date.now() - state.startTime;
  updateMessages(msgs =>
    msgs.map(m =>
      m.id === assistantId
        ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments], durationMs }
        : m
    )
  );
  if (convId && activeConversationIdRef.current !== convId) {
    messagesCacheRef.current.set(convId, state.messages);
  }
  cleanupStream();
  if (activeConversationIdRef.current === convId) {
    setIsStreaming(false);
  }

